from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==2 and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); comp=[]
   while q:
    x,y=q.popleft();comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]==2 and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   comps.append(comp)
[(len(q),(min(x for x,y in q),max(x for x,y in q),min(y for x,y in q),max(y for x,y in q)), any(y==5 for x,y in q)) for q in comps]

